#!/bin/bash
sed -i 's/app.get("\/api\/admin\/fornecedores\/:id\/produtos", authenticateToken, async (req: any, res) => {/app.get("\/api\/admin\/fornecedores\/:id\/produtos", authenticateToken, async (req: any, res) => {\n    if (req.user.role !== "admin" \&\& req.user.role !== "armazem") return res.sendStatus(403);\n    try {\n      const { period, month, year } = req.query;\n      let query = supabase.from("fatura_itens").select(`\n          produto_id,\n          quantidade,\n          preco_custo,\n          produtos ( nome, imagem_url ),\n          faturas!inner (\n             fornecedor_id,\n             data_emissao\n          )\n        `).eq("faturas.fornecedor_id", req.params.id);\n\n      if (period !== "todos") {\n         const m = month ? Number(month) : new Date().getMonth();\n         const y = year ? Number(year) : new Date().getFullYear();\n         const startDate = new Date(y, m, 1).toISOString();\n         const endDate = new Date(y, m + 1, 0, 23, 59, 59).toISOString();\n         query = query.gte("faturas.data_emissao", startDate).lte("faturas.data_emissao", endDate);\n      }\n      const { data, error } = await query;/g' src/routes/finance.ts
